#!/usr/bin/env python3
"""Offline M2.6 applicator. Each segment and the complete patch are SHA-256 checked."""
from __future__ import annotations
import argparse
import base64
import bz2
import hashlib
from pathlib import Path
import subprocess
import sys

EXPECTED_PATCH_SHA256 = "d9e4f1f05e352467287350619d6e8094b4501fc8923705dac23ba28bbbbd003c"
EXPECTED_PATCH_SIZE = 52807

# Each independently verifiable segment contains <=1000 compressed bytes.
CHUNKS = [
    ('881890afe4f0065a19318a3cb50ad76c56763dc08763d712bf42883b800b7891',
     ''),
    ('7d44304497c1a3aab164c8bd7337f1e10f9af3941ea3eff771192634e467a146',
     ''),
    ('484abacbe6211b317de9ea718fd7966f134417f5793f5a3240a872c2595093ff',
     ''),
    ('16ebb0f8833bfa721a2369808599953e14b7ab6d0c6cc019ca8fb97bcecb152f',
     ''),
    ('0df92569fad5cd75496b8eda8bfcb4d6b133e557f7c9ed8fa01816f5faf8f7af',
     ''),
    ('d081b945f8a5be404bae7bebc41b6f7338e1838ac87c668596811b3b98ad2c5a',
     ''),
    ('a048e04a1e84f130f388a30ffad5e426a356f34c5c07508d28add7e6bb235857',
     ''),
    ('2c54e0561c39879c192bd624baecafe3d0160055946802ebbe85d801309301b2',
     ''),
    ('d10c5c028547ac51b656f5ef8cacaa02f18fc156312277a1240f6394f46aa9f8',
     ''),
    ('217b629e99e32e59f1ee3bbda572e3547252c8084758e67962b35fd99119b2e0',
     ''),
    ('c36c41d7bad036e63731807f923f9aef8844ec6f670fb7ca15f2767a994fe1f5',
     ''),
    ('475b09787140534df199995617bde1d9c8af30ab6d095ff5b31d41206311d385',
     ''),
    ('3e9823c9337179de0ae14fe26d0f08c69e2821aff62464d5b3a3f084fba2f0fb',
     ''),
    ('73baf7f07604118c6fcf94dee0f3fd0f76b3bcbb9952ccb2eb8337b261316a90',
     ''),
    ('ca9f03a173163bdbbce27692cb198f7bd36abda31fbb40dd8b647487586c7604',
     'J62Rs1MGxD5+sOBUPHf9kn/0n7OM0+I1P/xdyRThQkAoHcZo'),
]

def reconstruct() -> bytes:
    compressed = bytearray()
    for number, (digest, encoded) in enumerate(CHUNKS, 1):
        try:
            part = base64.b64decode(encoded, validate=True)
        except (ValueError, base64.binascii.Error) as exc:
            raise ValueError(f"Damaged Base64 in segment {number}: {exc}") from exc
        if hashlib.sha256(part).hexdigest() != digest:
            raise ValueError(f"Incorrect SHA-256 in segment {number}")
        compressed.extend(part)
    try:
        data = bz2.decompress(compressed)
    except (OSError, EOFError) as exc:
        raise ValueError(f"Compressed patch cannot be decoded: {exc}") from exc
    if len(data) != EXPECTED_PATCH_SIZE or hashlib.sha256(data).hexdigest() != EXPECTED_PATCH_SHA256:
        raise ValueError("Complete reconstructed Git patch has the wrong SHA-256 or size")
    return data

def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Verify without applying')
    parser.add_argument('--write-patch', action='store_true', help='Write conventional patch only')
    args = parser.parse_args()
    try:
        data = reconstruct()
        print(f"PASS: M2.6 patch verified ({len(data)} bytes, {len(CHUNKS)} segments).")
        if args.write_patch:
            output = Path('ChromascopeIP-M2.6.recovered.patch')
            output.write_bytes(data)
            print(f"PASS: wrote {output} without modifying source files.")
            return 0
        check = subprocess.run(['git','apply','--check','--whitespace=error','-'], input=data, check=False)
        if check.returncode:
            print('ERROR: Patch does not apply to the current tree. M2.5 baseline or worktree differs.', file=sys.stderr)
            return check.returncode
        print('PASS: patch applies cleanly to the accepted M2.5 baseline.')
        if args.check: return 0
        result = subprocess.run(['git','apply','--whitespace=error','-'], input=data, check=False)
        if result.returncode == 0:
            print('PASS: applied M2.6. Next: git diff --check and native tests.')
        return result.returncode
    except ValueError as error:
        print(f'ERROR: {error}. No source files were changed.', file=sys.stderr)
        return 1

if __name__ == '__main__':
    sys.exit(main())
